@media (prefers-reduced-motion: reduce) {
  #game-stage #battlePage.v-fixed-slot-render-v2 .battle-player.v174-cardless-unit.active-turn > .v174-battle-art::before { opacity: 0.65; animation: auto ease 0s 1 normal none running none !important; }
  #game-stage #battlePage .v174-action-motion, #game-stage #battlePage .v174-portrait-paint, #game-stage #battlePage .v174-generic-portrait > .v174-action-motion::before { animation: auto ease 0s 1 normal none running none !important; }
  #game-stage #battlePage .v174-battle-art[data-motion="dying"] > .v174-action-motion { opacity: 0.35; }
  #game-stage #battlePage.v-fixed-slot-render-v2 .v174-cardless-unit.target::before, #game-stage #battlePage.v-fixed-slot-render-v2 .v174-cardless-unit.ally-targetable::before { animation: auto ease 0s 1 normal none running none !important; }
}
